create table if not exists public.social_community_contacts (id uuid primary key default gen_random_uuid(),provider text not null check (provider in ('instagram','facebook','tiktok','youtube')),external_user_id text not null,username text,display_name text,profile_url text,avatar_url text,person_type text not null default 'unknown' check (person_type in ('consumer','business','creator','support','press','unknown')),linked_user_id uuid,linked_crm_contact_id uuid,linked_crm_account_id uuid,first_seen_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb,unique(provider,external_user_id));
create table if not exists public.social_community_conversations (id uuid primary key default gen_random_uuid(),provider text not null check (provider in ('instagram','facebook','tiktok','youtube')),social_account_id uuid,contact_id uuid references public.social_community_contacts(id) on delete set null,external_thread_id text,conversation_type text not null default 'comment' check (conversation_type in ('comment','dm','mention','reply','story_mention','public_opportunity')),status text not null default 'needs_reply' check (status in ('needs_reply','ai_handled','human_handled','waiting','closed','spam','escalated')),person_type text not null default 'unknown',intent text,occasion text,area text,timing text,sentiment text not null default 'neutral' check (sentiment in ('positive','neutral','frustrated','negative','urgent')),opportunity_strength text not null default 'low' check (opportunity_strength in ('very_strong','good','low')),opportunity_score integer not null default 0 check (opportunity_score between 0 and 100),risk_level text not null default 'green' check (risk_level in ('green','yellow','red')),assigned_to_user_id uuid,source_post_id text,source_permalink text,first_message_at timestamptz not null default now(),last_message_at timestamptz not null default now(),converted_at timestamptz,metadata jsonb not null default '{}'::jsonb);
create table if not exists public.social_community_messages (id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.social_community_conversations(id) on delete cascade,provider text not null,external_message_id text,direction text not null check (direction in ('inbound','outbound')),sender_type text not null default 'consumer' check (sender_type in ('consumer','ai','human','system')),body text,status text not null default 'received' check (status in ('received','draft','approved','sent','failed','hidden')),sent_by_user_id uuid,created_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb,unique(provider,external_message_id));
create table if not exists public.social_growth_opportunities (id uuid primary key default gen_random_uuid(),provider text not null,opportunity_type text not null check (opportunity_type in ('public_intent','trend','content','creator','conversation')),external_id text,title text not null,summary text,intent text,area text,timing text,opportunity_strength text not null default 'good' check (opportunity_strength in ('very_strong','good','low')),score integer not null default 50 check (score between 0 and 100),source_url text,suggested_reply text,suggested_content jsonb not null default '{}'::jsonb,status text not null default 'new' check (status in ('new','reviewed','acted_on','skipped','expired')),discovered_at timestamptz not null default now(),expires_at timestamptz,metadata jsonb not null default '{}'::jsonb,unique(provider,external_id));
create table if not exists public.social_growth_daily_snapshots (id uuid primary key default gen_random_uuid(),snapshot_date date not null,provider text not null,followers_total bigint not null default 0,followers_gained bigint not null default 0,followers_lost bigint not null default 0,reach bigint not null default 0,profile_visits bigint not null default 0,website_visits bigint not null default 0,outing_searches bigint not null default 0,outing_selections bigint not null default 0,high_intent_actions bigint not null default 0,business_leads bigint not null default 0,paid_customers bigint not null default 0,new_mrr numeric(12,2) not null default 0,top_theme text,top_area text,top_format text,metadata jsonb not null default '{}'::jsonb,unique(snapshot_date,provider));
create table if not exists public.social_manager_settings (id uuid primary key default gen_random_uuid(),scope text not null default 'platform' unique,operating_mode text not null default 'assisted' check (operating_mode in ('suggest','assisted','autopilot')),handle_basic_questions boolean not null default true,handle_outing_requests boolean not null default true,handle_business_questions boolean not null default false,handle_creator_questions boolean not null default false,handle_comments boolean not null default true,handle_direct_messages boolean not null default true,always_human_topics text[] not null default array['complaints','payments','legal','safety','media','partnership_negotiations']::text[],public_discovery_enabled boolean not null default false,updated_at timestamptz not null default now(),updated_by_user_id uuid);
insert into public.social_manager_settings(scope) values ('platform') on conflict (scope) do nothing;
create index if not exists social_community_conversations_status_idx on public.social_community_conversations(status,last_message_at desc);
create index if not exists social_community_conversations_person_idx on public.social_community_conversations(person_type,opportunity_score desc);
create index if not exists social_community_messages_conversation_idx on public.social_community_messages(conversation_id,created_at);
create index if not exists social_growth_opportunities_status_idx on public.social_growth_opportunities(status,score desc,discovered_at desc);
create index if not exists social_growth_daily_snapshots_date_idx on public.social_growth_daily_snapshots(snapshot_date desc,provider);
alter table public.social_community_contacts enable row level security;alter table public.social_community_conversations enable row level security;alter table public.social_community_messages enable row level security;alter table public.social_growth_opportunities enable row level security;alter table public.social_growth_daily_snapshots enable row level security;alter table public.social_manager_settings enable row level security;
revoke all on public.social_community_contacts from anon,authenticated;revoke all on public.social_community_conversations from anon,authenticated;revoke all on public.social_community_messages from anon,authenticated;revoke all on public.social_growth_opportunities from anon,authenticated;revoke all on public.social_growth_daily_snapshots from anon,authenticated;revoke all on public.social_manager_settings from anon,authenticated;